    20	    /**
    21	     * We may need to shift the Tooltip horizontally as some of the inline text wraps well with ellipsis,
    22	     * but their container node overflows the parent view which causes the tooltip to be misplaced.
    23	     *
    24	     * So we shift it by calculating it as follows:
    25	     * 1. We get the container layout and take the Child inline text node.
    26	     * 2. Now we get the tooltip original position.
    27	     * 3. If inline node's right edge is overflowing the container's right edge, we set the tooltip to the center
    28	     * of the distance between the left edge of the inline node and right edge of the container.
    29	     * @param index Used to get the Ref to the node at the current index
    30	     * @returns Distance to shift the tooltip horizontally
    31	     */
    32	    const getTooltipShiftX = useCallback((index: number) => {
    33	        // Only shift the tooltip in case the containerLayout or Refs to the text node are available
    34	        if (!containerRef.current || !childRefs.current[index]) {
    35	            return 0;
    36	        }
