    37	    isAnonymousAction?: boolean;
    38	
    39	    /** Whether the menu item is focused or not */
    40	    isFocused?: boolean;
    41	
    42	    /** Whether the width should be limited */
    43	    shouldLimitWidth?: boolean;
    44	
    45	    /** Styles to apply to ManuItem wrapper */
    46	    wrapperStyle?: StyleProp<ViewStyle>;
    47	
    48	    shouldPreventDefaultFocusOnPress?: boolean;
    49	
    50	    /** The ref of mini context menu item */
    51	    buttonRef?: React.RefObject<View>;
    52	
    53	    /** Handles what to do when the item is focused */
    54	    onFocus?: () => void;
    55	
    56	    /** Handles what to do when the item loose focus */
    57	    onBlur?: () => void;
    58	
    59	    /** Whether the menu item is disabled or not */
    60	    disabled?: boolean;
    61	
    62	    /** Whether the menu item should show loading icon */
    63	    shouldShowLoadingSpinnerIcon?: boolean;
    64	};
    65	
    66	type ContextMenuItemHandle = {
    67	    triggerPressAndUpdateSuccess?: () => void;
    68	};
    69	
    70	function ContextMenuItem(
    71	    {
    72	        onPress,
    73	        successIcon,
    74	        successText = '',
    75	        icon,
    76	        text,
    77	        isMini = false,
    78	        description = '',
    79	        isAnonymousAction = false,
    80	        isFocused = false,
    81	        shouldLimitWidth = true,
    82	        wrapperStyle,
    83	        shouldPreventDefaultFocusOnPress = true,
    84	        buttonRef = {current: null},
    85	        onFocus = () => {},
    86	        onBlur = () => {},
    87	        disabled = false,
    88	        shouldShowLoadingSpinnerIcon = false,
    89	    }: ContextMenuItemProps,
    90	    ref: ForwardedRef<ContextMenuItemHandle>,
    91	) {
    92	    const styles = useThemeStyles();
    93	    const StyleUtils = useStyleUtils();
    94	    const {windowWidth} = useWindowDimensions();
    95	    const [isThrottledButtonActive, setThrottledButtonInactive] = useThrottledButtonState();
    96	
    97	    const triggerPressAndUpdateSuccess = (event?: GestureResponderEvent | MouseEvent | KeyboardEvent) => {
    98	        if (!isThrottledButtonActive) {
    99	            return;
   100	        }
   101	        onPress(event);
   102	
   103	        // We only set the success state when we have icon or text to represent the success state
   104	        // We may want to replace this check by checking the Result from OnPress Callback in future.
   105	        if (!!successIcon || successText) {
   106	            setThrottledButtonInactive();
   107	        }
   108	    };
   109	
   110	    useImperativeHandle(ref, () => ({triggerPressAndUpdateSuccess}));
   111	
   112	    const itemIcon = !isThrottledButtonActive && successIcon ? successIcon : icon;
   113	    const itemText = !isThrottledButtonActive && successText ? successText : text;
   114	
   115	    return isMini ? (
   116	        <BaseMiniContextMenuItem
   117	            ref={buttonRef}
   118	            tooltipText={itemText}
   119	            onPress={triggerPressAndUpdateSuccess}
   120	            isDelayButtonStateComplete={!isThrottledButtonActive}
   121	            shouldPreventDefaultFocusOnPress={shouldPreventDefaultFocusOnPress}
   122	        >
   123	            {({hovered, pressed}) => (
   124	                <Icon
   125	                    small
   126	                    src={itemIcon}
   127	                    fill={StyleUtils.getIconFillColor(getButtonState(hovered, pressed, !isThrottledButtonActive))}
   128	                />
   129	            )}
   130	        </BaseMiniContextMenuItem>
   131	    ) : (
   132	        <FocusableMenuItem
   133	            title={itemText}
   134	            icon={itemIcon}
   135	            onPress={triggerPressAndUpdateSuccess}
   136	            wrapperStyle={[styles.pr9, wrapperStyle]}
   137	            success={!isThrottledButtonActive}
   138	            description={description}
   139	            descriptionTextStyle={styles.breakWord}
   140	            style={shouldLimitWidth && StyleUtils.getContextMenuItemStyles(windowWidth)}
   141	            isAnonymousAction={isAnonymousAction}
   142	            focused={isFocused}
   143	            interactive={isThrottledButtonActive}
   144	            onFocus={onFocus}
   145	            onBlur={onBlur}
   146	            disabled={disabled}
   147	            shouldShowLoadingSpinnerIcon={shouldShowLoadingSpinnerIcon}
   148	        />
   149	    );
   150	}
   151	
   152	ContextMenuItem.displayName = 'ContextMenuItem';
   153	
   154	export default forwardRef(ContextMenuItem);
   155	export type {ContextMenuItemHandle};
